/* Standalone controls refuse non-guest invocation before exercising syscalls. */
#include <ctype.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static int parity_read_line(const char *path, char *out, size_t capacity)
{
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    size_t n = fread(out, 1, capacity - 1, f);
    int extra = fgetc(f), bad = ferror(f);
    if (fclose(f)) bad = 1;
    if (bad || extra != EOF) return 0;
    while (n && (out[n-1]=='\n' || out[n-1]=='\r')) --n;
    out[n] = 0;
    return n > 0 && strlen(out) == n;
}

static int parity_require_guest(void)
{
    char cwd[PATH_MAX], marker[64], vendor[32];
    const char *home = getenv("HOME");
    if (geteuid()!=2000 || !getcwd(cwd,sizeof cwd) || strcmp(cwd,"/tmp/parity-case") ||
        !home || strcmp(home,"/tmp/parity-home")) goto refuse;
    if (!parity_read_line("/etc/bashos-parity-vm",marker,sizeof marker) || strlen(marker)!=36 ||
        !parity_read_line("/sys/class/dmi/id/sys_vendor",vendor,sizeof vendor) || strcmp(vendor,"QEMU")) goto refuse;
    for (int i=0; i<36; ++i) {
        if (i==8 || i==13 || i==18 || i==23) { if (marker[i]!='-') goto refuse; }
        else if (!isxdigit((unsigned char)marker[i])) goto refuse;
    }
    return 1;
refuse:
    fputs("refusing execution outside disposable parity VM\n",stderr);
    return 0;
}

/* SPDX-License-Identifier: MIT */
#include <unistd.h>
#include <sys/syscall.h>
#include <linux/keyctl.h>
#include <errno.h>
#include <stdio.h>
_Static_assert(SYS_add_key == 248 && SYS_keyctl == 250, "x86-64 syscall ABI");
_Static_assert(KEY_SPEC_THREAD_KEYRING == -1 && KEY_SPEC_PROCESS_KEYRING == -2 && KEY_SPEC_SESSION_KEYRING == -3, "special IDs");
_Static_assert(KEY_SPEC_USER_KEYRING == -4 && KEY_SPEC_USER_SESSION_KEYRING == -5 && KEY_SPEC_GROUP_KEYRING == -6, "special IDs");
_Static_assert(KEYCTL_JOIN_SESSION_KEYRING == 1 && KEYCTL_CLEAR == 7 && KEYCTL_SEARCH == 10 && KEYCTL_READ == 11, "keyctl operations");
int main(void) {
  if (!parity_require_guest()) return 125;
  /* These requests are intrinsically nonmutating even if run without the
     mock: READ uses an absent serial and add_key has a NULL type pointer. */
  errno=0;
  if(syscall(SYS_keyctl, KEYCTL_READ, 2147483647, 0, 0, 0)!=-1 || errno!=EPERM) return 11;
  errno=0;
  if(syscall(SYS_add_key,(const char *)0,(const char *)0,(const void *)0,0,0)!=-1 || errno!=EPERM) return 12;
  puts("probe ok"); return 0;
}

