# SPDX-License-Identifier: MIT
# Guest-only, direct Linux keyring observer. Every mutation is preceded by a
# new anonymous or unpredictable named session ring owned by this process.
import ctypes
import errno
import json
import os
from pathlib import Path
import secrets
import stat
import struct
import sys


import uuid


def require_parity_guest():
    # The root evaluator independently verifies the UUID against QEMU's DMI UUID.
    try:
        if os.geteuid() != 2000 or Path.cwd() != Path('/tmp/parity-case'):
            raise ValueError('wrong uid or scratch directory')
        if os.environ.get('HOME') != '/tmp/parity-home':
            raise ValueError('wrong scratch HOME')
        marker = Path('/etc/bashos-parity-vm').read_text(encoding='ascii').strip()
        if str(uuid.UUID(marker)) != marker.lower():
            raise ValueError('noncanonical VM marker')
        if Path('/sys/class/dmi/id/sys_vendor').read_text(encoding='ascii').strip() != 'QEMU':
            raise ValueError('not QEMU')
    except (OSError, ValueError, UnicodeError) as exc:
        sys.stderr.write('refusing execution outside disposable parity VM: %s\n' % exc)
        raise SystemExit(125)


require_parity_guest()

LIB=ctypes.CDLL(None,use_errno=True)
LIB.syscall.restype=ctypes.c_long
SYS_ADD_KEY=248
SYS_KEYCTL=250
SESSION=-3


def call(n,*args):
    converted=[]
    keep=[]
    for a in args:
        if isinstance(a,int):
            converted.append(ctypes.c_long(a))
        elif isinstance(a,bytes):
            b=ctypes.create_string_buffer(a); keep.append(b); converted.append(ctypes.cast(b,ctypes.c_void_p))
        elif a is None:
            converted.append(ctypes.c_void_p(0))
        else:
            converted.append(ctypes.cast(a,ctypes.c_void_p))
    ctypes.set_errno(0)
    v=LIB.syscall(ctypes.c_long(n),*converted)
    err=ctypes.get_errno() if v == -1 else 0
    described=[a if isinstance(a,int) or a is None else
               {'bytes_hex':a[:4096].hex(),'length':len(a)} if isinstance(a,bytes) else '<buffer>' for a in args]
    oracle_raw({'observation':'syscall','number':n,'args':described,'result':int(v),'errno':err})
    if v == -1:
        raise OSError(err,os.strerror(err))
    return int(v)


def kc(op,*args):
    return call(SYS_KEYCTL,op,*args)


def read_key(serial):
    n=kc(11,serial,None,0,0)
    buf=ctypes.create_string_buffer(max(n,1))
    got=kc(11,serial,buf,n,0)
    if got>n: raise RuntimeError('fixture key grew')
    data=bytes(buf.raw[:got])
    oracle_raw({'observation':'read','serial':serial,'reported_size':n,'returned_size':got,
                'data_hex':data[:8192].hex(),'truncated':len(data)>8192})
    return data


def oracle_raw(record):
    with (Path(os.environ['HOME'])/'keyctl-proc.jsonl').open('a', encoding='utf-8') as f:
        f.write(json.dumps(record,sort_keys=True)+'\n')


def proc(serial):
    for line in Path('/proc/keys').read_text().splitlines():
        fields=line.split()
        if fields and int(fields[0],16)==serial:
            oracle_raw({'observation':'proc','serial':serial,'uid':os.geteuid(),'line':line[:4096]})
            return line,fields
    oracle_raw({'observation':'proc','serial':serial,'uid':os.geteuid(),'line':None})
    raise RuntimeError('key missing from /proc/keys: %x'%serial)


def expect_proc(serial,name=None,revoked=False,empty=False):
    line,fields=proc(serial)
    if len(fields)<9 or int(fields[5])!=os.geteuid(): raise RuntimeError('bad proc owner '+line)
    if name is not None and name not in ' '.join(fields[8:]): raise RuntimeError('bad proc name '+line)
    if revoked and 'R' not in fields[1]: raise RuntimeError('not revoked in proc '+line)
    if empty and (fields[7]!='keyring' or not line.rstrip().endswith(': empty')): raise RuntimeError('not empty in proc '+line)


def restrict(serial,owned_ring):
    # KEYCTL_READ also permits a searched/possessed key, so remove SEARCH as
    # well as READ. Keep VIEW and SETATTR for the possessing owner.
    current=kc(0,SESSION,0,0,0)
    if current!=owned_ring: raise RuntimeError('session is not the fixture-owned ring')
    line,fields=proc(owned_ring)
    if len(fields)<9 or fields[7]!='keyring' or int(fields[5])!=os.geteuid():
        raise RuntimeError('fixture ring ownership cannot be established')
    links=read_key(owned_ring)
    if len(links)%4 or serial not in [x[0] for x in struct.iter_unpack('<i',links)]:
        raise RuntimeError('key is not linked to the fixture-owned ring')
    mask=0x21210000
    oracle_raw({'observation':'restriction-attempt','ring':owned_ring,'serial':serial,
                'desired_mask_hex':format(mask,'08x'),'linked_serials_hex':links.hex()})
    kc(5,serial,mask,0,0)
    line,fields=proc(serial)
    if int(fields[4],16)!=mask: raise RuntimeError('unexpected permissions '+line)


def parent_owned_ring():
    marker=Path(os.environ['HOME'])/'keyctl-owned-ring'
    info=marker.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid!=os.geteuid() or stat.S_IMODE(info.st_mode)!=0o600:
        raise RuntimeError('owned-ring marker is not private')
    parent,ring=map(int,marker.read_text().split())
    oracle_raw({'observation':'owned-ring-marker','recorded_parent':parent,
                'actual_parent':os.getppid(),'ring':ring,'mode':stat.S_IMODE(info.st_mode),'uid':info.st_uid})
    if parent!=os.getppid() or ring<=0:
        raise RuntimeError('owned-ring marker does not identify this parent')
    return ring


def control():
    assert os.geteuid()==2000, 'fixture must run as uid 2000'
    ring=kc(1,None,0,0,0)
    assert ring>0 and kc(0,SESSION,0,0,0)==ring
    payload=b'\x00independent\xff'
    key=call(SYS_ADD_KEY,b'user',b'fixture-key-oracle-control',payload,len(payload),SESSION)
    assert key>0 and kc(10,SESSION,b'user',b'fixture-key-oracle-control',0)==key
    assert read_key(key)==payload
    denied=call(SYS_ADD_KEY,b'user',b'fixture-key-oracle-denied',payload,len(payload),SESSION)
    assert read_key(denied)==payload
    restrict(denied,ring)
    try:
        read_key(denied)
    except OSError as e:
        assert e.errno==errno.EACCES
    else:
        raise RuntimeError('permission control did not deny read')
    kc(3,key,0,0,0); expect_proc(key,revoked=True)
    kc(7,SESSION,0,0,0); assert read_key(ring)==b''; expect_proc(ring,empty=True)
    name='fixture-key-oracle-'+secrets.token_hex(16)
    assert not any(name in line for line in Path('/proc/keys').read_text().splitlines())
    named=kc(1,name.encode(),0,0,0)
    assert named>0 and kc(0,SESSION,0,0,0)==named
    expect_proc(named,name=name)
    print('independent private keyring and proc controls ok')


def main():
    cmd=sys.argv[1]
    if cmd=='control': control()
    elif cmd=='ring': print(kc(0,SESSION,0,0,0))
    elif cmd=='read': sys.stdout.buffer.write(read_key(int(sys.argv[2])))
    elif cmd=='revoked': expect_proc(int(sys.argv[2]),revoked=True)
    elif cmd=='restrict': restrict(int(sys.argv[2]),parent_owned_ring())
    elif cmd=='named': expect_proc(int(sys.argv[2]),name=sys.argv[3])
    elif cmd=='empty':
        serial=int(sys.argv[2]); assert read_key(serial)==b''; expect_proc(serial,empty=True)
    elif cmd=='absent':
        matches=[line[:4096] for line in Path('/proc/keys').read_text().splitlines() if sys.argv[2] in line]
        oracle_raw({'observation':'name-absence','name':sys.argv[2], 'matching_lines':matches[:16],
                    'truncated':len(matches)>16})
        assert not matches
    elif cmd=='unique': print('fixture-key-keytest-'+secrets.token_hex(16))
    else: raise ValueError(cmd)


if __name__=='__main__':
    try: main()
    except Exception as e:
        print('oracle failed: '+str(e),file=sys.stderr)
        sys.exit(1)

